<?php
namespace SignalPilot\MarketData;use SignalPilot\Contracts\MarketDataProviderInterface;
class SimulatedMarketDataProvider implements MarketDataProviderInterface{public function quote(string $s):array{$seed=crc32($s.date('Y-m-d-H'));$price=round(20+($seed%25000)/100,2);return ['symbol'=>strtoupper($s),'price'=>$price,'volume'=>100000+($seed%9000000),'time'=>date('c')];} public function indicators(string $s):array{$q=$this->quote($s);$p=$q['price'];return $q+['trend'=>($p%2>1?'up':'sideways'),'momentum'=>round((($p%10)-5)/10,2),'vwap'=>round($p*0.995,2),'ma20'=>round($p*0.985,2),'ma50'=>round($p*0.97,2),'opening_range_high'=>round($p*1.01,2),'opening_range_low'=>round($p*.99,2)];} public function marketStatus():array{$d=(int)date('N');$h=(int)date('G');return ['open'=>$d<6&&$h>=13&&$h<=20,'label'=>($d<6&&$h>=13&&$h<=20)?'Open':'Closed/After Hours'];}}
